import type { Instrument, MusicEffects, SoundDesign, Track } from './audio-types';

/** The jingles a game plays once (P12-R07). */
export type Jingle = 'complete' | 'over' | 'checkpoint';

/** Which music is wanted (P12-R06..R08). */
export type MusicRequest =
  | { readonly kind: 'menu' }
  | { readonly kind: 'level'; readonly levelId: string }
  | { readonly kind: 'boss'; readonly levelId: string }
  | { readonly kind: 'jingle'; readonly jingle: Jingle };

/**
 * A game's music and sounds (`GameView.audio`, P12-R05..R10): all generated by code from data.
 * The engine knows the moments (cues, see `SoundCue`) and the music wanted; the game decides
 * how they sound.
 */
export interface AudioBindings {
  /** The track for a request, made once and kept; undefined: silence. */
  readonly music: (request: MusicRequest) => Track | undefined;
  /** The instruments the tracks' notes name. */
  readonly instruments: Readonly<Record<string, Instrument>>;
  /** The sound of each cue (`SoundCue.cue`); cues without one are silent. */
  readonly sounds: Readonly<Record<string, SoundDesign>>;
  /** Explosions at least this big (radius, logical pixels) play `blast-large`. */
  readonly largeBlastRadius: number;
  /** Levels of the music and sound effect buses at full volume. */
  readonly mix: { readonly music: number; readonly sfx: number };
  /** The music's echo and reverb (instruments send to them); dry when omitted. */
  readonly effects?: MusicEffects;
}
